"""Skill-oriented tracker/event helpers shared across orchestration."""

from __future__ import annotations

from typing import Optional

from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.default_skills import (
    DEFAULT_COMPLETED,
    DEFAULT_COMPLETED_TARGET_ID,
    DEFAULT_CONTINUE_INTERRUPTED,
    DEFAULT_CONTINUE_INTERRUPTED_FLOW_ID,
    DEFAULT_CUSTOMER_SATISFACTION,
    DEFAULT_CUSTOMER_SATISFACTION_FLOW_ID,
    DEFAULT_SESSION_START,
    DEFAULT_SESSION_START_FLOW_ID,
    DEFAULT_SILENCE_TIMEOUT,
    DEFAULT_SILENCE_TIMEOUT_FLOW_ID,
    DEFAULT_SILENCE_TIMEOUT_HANGUP,
    DEFAULT_SILENCE_TIMEOUT_HANGUP_FLOW_ID,
    DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
    DEFAULT_UNSUPPORTED_REQUEST_HANDLER_FLOW_ID,
)
from rasa.mantle.skills.catalog import (
    SkillCatalog,
    entry_target_id_for_skill,
)
from rasa.mantle.skills.skill import Skill
from rasa.mantle.skills.stack_frame_helpers import MantlePathFrame, target_id_for_frame
from rasa.shared.core.events import OrderedBlockEntered, SkillActivated

LIFECYCLE_DEFAULT_SKILL_IDS = frozenset(
    {
        DEFAULT_COMPLETED,
        DEFAULT_CONTINUE_INTERRUPTED,
        DEFAULT_CUSTOMER_SATISFACTION,
        DEFAULT_SESSION_START,
        DEFAULT_SILENCE_TIMEOUT,
        DEFAULT_SILENCE_TIMEOUT_HANGUP,
        DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
    }
)
LIFECYCLE_DEFAULT_SKILL_BY_BUNDLED_BLOCK_ID = {
    DEFAULT_COMPLETED_TARGET_ID: DEFAULT_COMPLETED,
    DEFAULT_CONTINUE_INTERRUPTED_FLOW_ID: DEFAULT_CONTINUE_INTERRUPTED,
    DEFAULT_CUSTOMER_SATISFACTION_FLOW_ID: DEFAULT_CUSTOMER_SATISFACTION,
    DEFAULT_SESSION_START_FLOW_ID: DEFAULT_SESSION_START,
    DEFAULT_SILENCE_TIMEOUT_FLOW_ID: DEFAULT_SILENCE_TIMEOUT,
    DEFAULT_SILENCE_TIMEOUT_HANGUP_FLOW_ID: DEFAULT_SILENCE_TIMEOUT_HANGUP,
    DEFAULT_UNSUPPORTED_REQUEST_HANDLER_FLOW_ID: DEFAULT_UNSUPPORTED_REQUEST_HANDLER,
}
_WRAP_UP_OR_CSAT_SKILL_IDS = frozenset(
    {DEFAULT_COMPLETED, DEFAULT_CUSTOMER_SATISFACTION}
)
_DISCARD_BEFORE_ACTIVATE_SKILL_IDS = frozenset(
    {
        DEFAULT_COMPLETED,
        DEFAULT_CONTINUE_INTERRUPTED,
        DEFAULT_CUSTOMER_SATISFACTION,
    }
)


def find_activation_index(
    events_list: list,
    *,
    skill_id: str,
    block_id: Optional[str] = None,
) -> Optional[int]:
    """Return the index of the most recent activation anchor for a skill or block.

    Without *block_id*, the anchor is the last ``SkillActivated`` for
    *skill_id*; with it, the last ``OrderedBlockEntered`` for that
    ``(skill_id, block_id)``. Returns ``None`` when no anchor exists.
    """
    for index in range(len(events_list) - 1, -1, -1):
        event = events_list[index]
        if block_id is None:
            if isinstance(event, SkillActivated) and event.skill_id == skill_id:
                return index
        elif (
            isinstance(event, OrderedBlockEntered)
            and event.skill_id == skill_id
            and event.block_id == block_id
        ):
            return index
    return None


def should_record_digression(*, target_skill_id: Optional[str]) -> bool:
    """Return whether an INTERRUPT should stamp digression metadata for eval.

    ``True`` when the user switches to another skill (task digression). ``False``
    when activating the unsupported-request handler — that interrupt is stack
    bookkeeping behind ``cannot_help``, not a task switch; the eval report uses
    ``UnsupportedRequestClassified`` instead.
    """
    return target_skill_id != DEFAULT_UNSUPPORTED_REQUEST_HANDLER


def entry_id_for_skill_id(catalog: SkillCatalog, skill_id: str) -> Optional[str]:
    """Return the catalog entry ID for *skill_id*, if that skill is loaded.

    Bundled lifecycle defaults compile to the ordered block
    ``{skill_id}__main``. A project prose override of the same skill id
    compiles as an entry whose id is ``skill_id``. Callers must not
    assume the bundled ordered-block id still exists.
    """
    skill = catalog.skill_by_id(skill_id)
    if skill is None:
        return None
    return entry_target_id_for_skill(skill)


def skill_for_stack_frame(
    catalog: SkillCatalog,
    frame: MantlePathFrame | None,
) -> Skill | None:
    """Return the skill that owns *frame*, if any."""
    if frame is None:
        return None
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return catalog.skill_by_id(frame.skill_id)
    if frame.skill_id is not None:
        return catalog.skill_by_id(frame.skill_id)
    return catalog.owning_skill_for_target_id(frame.flow_id)


def owning_skill_id_for_frame(
    catalog: SkillCatalog, frame: MantlePathFrame
) -> Optional[str]:
    """Return the owning skill, including bundled IDs absent from the catalog."""
    if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
        return frame.skill_id
    if frame.skill_id is not None:
        return frame.skill_id
    owning_skill = catalog.owning_skill_for_target_id(frame.flow_id)
    if owning_skill is not None:
        return owning_skill.id
    return LIFECYCLE_DEFAULT_SKILL_BY_BUNDLED_BLOCK_ID.get(frame.flow_id)


def lifecycle_skill_id_for_block(
    catalog: SkillCatalog, compiled_id: Optional[str]
) -> Optional[str]:
    """Return the lifecycle default owning *compiled_id*, including old ids."""
    if compiled_id is None:
        return None
    skill = catalog.owning_skill_for_target_id(compiled_id)
    if skill is not None and skill.is_default:
        return skill.id
    if compiled_id in LIFECYCLE_DEFAULT_SKILL_IDS:
        return compiled_id
    return LIFECYCLE_DEFAULT_SKILL_BY_BUNDLED_BLOCK_ID.get(compiled_id)


def lifecycle_skill_id_for_frame(
    catalog: SkillCatalog,
    frame: MantlePathFrame | None,
) -> Optional[str]:
    """Return the lifecycle default that owns *frame*, including old cursors."""
    if frame is None:
        return None
    skill = skill_for_stack_frame(catalog, frame)
    if skill is not None and skill.is_default:
        return skill.id
    skill_id = owning_skill_id_for_frame(catalog, frame)
    if skill_id in LIFECYCLE_DEFAULT_SKILL_IDS:
        return skill_id
    return LIFECYCLE_DEFAULT_SKILL_BY_BUNDLED_BLOCK_ID.get(target_id_for_frame(frame))


def is_wrap_up_or_csat_block(catalog: SkillCatalog, compiled_id: Optional[str]) -> bool:
    """Return whether *compiled_id* belongs to wrap-up or CSAT.

    Bundled defaults use the ordered block ``{skill_id}__main``; a prose
    override compiles as the skill id. Both shapes are discarded before a
    follow-up task is pushed.
    """
    return (
        lifecycle_skill_id_for_block(catalog, compiled_id) in _WRAP_UP_OR_CSAT_SKILL_IDS
    )


def should_discard_default_before_activate(
    catalog: SkillCatalog,
    active_frame: MantlePathFrame | None,
    target_skill: Optional[Skill],
) -> bool:
    """Return whether activation abandons the active lifecycle prompt."""
    active_skill_id = lifecycle_skill_id_for_frame(catalog, active_frame)
    return (
        active_skill_id in _DISCARD_BEFORE_ACTIVATE_SKILL_IDS
        and target_skill is not None
        and not target_skill.is_default
        and target_skill.id != active_skill_id
    )
